+/// Remove a canonical field passenger's proven-zero 257th lane while an EEA
+/// traversal owns the peak. One reset records the clean release; the physical ID
+/// remains reserved until the symmetric restore.
+pub(super) fn release_canonical_passenger_top(
+    c: &mut Circuit,
+    passenger: &mut Vec<QReg>,
+    context: &str,
+) -> ReleasedCanonicalPassengerTop {
+    use crate::circuit::{OperationType, QubitId};
+
+    assert!(canonical_passenger_top_lifetime_enabled());
+    assert_eq!(
+        passenger.len(),
+        257,
+        "{context} canonical passenger must enter EEA with 257 lanes"
+    );
+    let live_before = c.b.active_qubits as usize;
+    c.flush_pending_frees();
+    let top = passenger.pop().expect("canonical passenger top lane");
+    let physical_id = top.id();
+    let resets_before = c.b.counted_kind_ops[OperationType::R as usize];
+    c.b.free(QubitId(physical_id.into()));
+    assert_eq!(
+        c.b.counted_kind_ops[OperationType::R as usize],
+        resets_before + 1,
+        "{context} canonical passenger release must emit one reset"
+    );
+    let free_position = c
+        .b
+        .free_qubits
+        .iter()
+        .position(|&id| id == physical_id)
+        .expect("released canonical passenger ID missing from free list");
+    c.b.free_qubits.swap_remove(free_position);
+    assert!(
+        !c.b.free_qubits.contains(&physical_id),
+        "{context} canonical passenger ID was not reserved"
+    );
+    assert_eq!(passenger.len(), 256, "{context} canonical passenger width");
+    assert_eq!(
+        c.b.active_qubits as usize + 1,
+        live_before,
+        "{context} canonical passenger release must save one live qubit"
+    );
+    c.lowq_passenger_top_releases += 1;
+    ReleasedCanonicalPassengerTop {
+        lane: Some(top),
+        physical_id,
+    }
+}
+
+pub(super) fn restore_canonical_passenger_top(
+    c: &mut Circuit,
+    passenger: &mut Vec<QReg>,
+    mut released: ReleasedCanonicalPassengerTop,
+    context: &str,
+) {
+    use crate::circuit::QubitId;
+
+    assert!(canonical_passenger_top_lifetime_enabled());
+    assert_eq!(
+        passenger.len(),
+        256,
+        "{context} canonical passenger must leave EEA with 256 lanes"
+    );
+    let live_before = c.b.active_qubits as usize;
+    let physical_id = released.physical_id;
+    assert!(
+        !c.b.free_qubits.contains(&physical_id),
+        "{context} reserved passenger ID became allocator-visible"
+    );
+    c.b.free_qubits.push(physical_id);
+    c.b.reacquire(QubitId(physical_id.into()));
+    let lane = released
+        .lane
+        .take()
+        .expect("canonical passenger top restored twice");
+    assert_eq!(
+        lane.id(),
+        physical_id,
+        "{context} restored a different physical passenger lane"
+    );
+    passenger.push(lane);
+    assert_eq!(passenger.len(), 257, "canonical passenger API requires 257 lanes");
+    assert_eq!(
+        passenger[256].id(),
+        physical_id,
+        "{context} passenger top physical identity changed"
+    );
+    assert_eq!(
+        c.b.active_qubits as usize,
+        live_before + 1,
+        "{context} passenger top restoration must reacquire one clean qubit"
+    );
+    assert!(
+        c.lowq_passenger_top_releases > 0,
+        "passenger release state underflow"
+    );
+    c.lowq_passenger_top_releases -= 1;
+}

+impl OpStreamWriter {
+    fn from_env() -> Option<Self> {
+        let path = std::env::var_os("POINT_ADD_STREAM_OPS_PATH")?;
+        Some(
+            Self::new(Path::new(&path))
+                .unwrap_or_else(|error| panic!("create streaming ops writer: {error}")),
+        )
+    }
+
+    fn new(path: &Path) -> std::io::Result<Self> {
+        let final_path = path.to_path_buf();
+        let temporary_path = path.with_extension("bin.tmp");
+        let mut writer = BufWriter::new(File::create(&temporary_path)?);
+        writer.write_all(STREAM_OPS_MAGIC)?;
+        writer.write_all(&0_u64.to_le_bytes())?;
+        let level = std::env::var("ZSTD_LEVEL")
+            .ok()
+            .and_then(|value| value.trim().parse().ok())
+            .unwrap_or(3);
+        let encoder = zstd::stream::write::Encoder::new(writer, level)?;
+        Ok(Self {
+            encoder: Some(encoder),
+            final_path,
+            temporary_path,
+            count: 0,
+        })
+    }
+
+    fn write_op(&mut self, op: &Op) -> std::io::Result<()> {
+        let mut record = [0_u8; STREAM_OP_BYTES];
+        record[0..4].copy_from_slice(&(op.kind as u32).to_le_bytes());
+        record[8..16].copy_from_slice(&op.q_control2.0.to_le_bytes());
+        record[16..24].copy_from_slice(&op.q_control1.0.to_le_bytes());
+        record[24..32].copy_from_slice(&op.q_target.0.to_le_bytes());
+        record[32..40].copy_from_slice(&op.c_target.0.to_le_bytes());
+        record[40..48].copy_from_slice(&op.c_condition.0.to_le_bytes());
+        record[48..56].copy_from_slice(&op.r_target.0.to_le_bytes());
+        self.encoder
+            .as_mut()
+            .expect("streaming ops encoder")
+            .write_all(&record)?;
+        self.count += 1;
+        Ok(())
+    }
+
+    fn finish(mut self) -> std::io::Result<u64> {
+        let encoder = self.encoder.take().expect("streaming ops encoder");
+        let mut writer = encoder.finish()?;
+        writer.flush()?;
+        drop(writer);
+
+        let mut header = OpenOptions::new().write(true).open(&self.temporary_path)?;
+        header.seek(SeekFrom::Start(STREAM_OPS_MAGIC.len() as u64))?;
+        header.write_all(&self.count.to_le_bytes())?;
+        header.flush()?;
+        drop(header);
+        fs::rename(&self.temporary_path, &self.final_path)?;
+        Ok(self.count)
+    }

+pub(crate) fn round763_compress_lever_enabled() -> bool {
+    // Reachable-support rewrite of the round763 6->5 sidecar packer. Each raw
+    // slot is (b0, b0_and_b1), with b0_and_b1 = b0 & (v<u), so state (0,1) is
+    // unreachable on the verifier support. On that support, three CCX collapse
+    // to CX and the compressor drops from 9 CCX to 4 CCX per direction.
+    std::env::var("DIALOG_GCD_ROUND763_COMPRESS_LEVER")
+        .ok()
+        .as_deref()
+        == Some("1")
 }

